def plot_raw_fans(tile_id, ax=None, dbname=None, **kwargs):
    """Plot all raw fan markings from the classifications database for a tile.

    Parameters
    ----------
    tile_id : str
        Planet Four tile ID (full or short form).
    ax : matplotlib.axes.Axes, optional
        Axes to plot on. If None, a new figure is created.
    dbname : str or Path, optional
        Path to database file. If None, uses ``[planet4_db] dbname`` from config.
    **kwargs
        Passed through to TileID.plot_fans (e.g. with_center, lw).
    """
    dbname = _resolve_dbname(dbname)
    imgid = _ProdTileID(tile_id, scope="planet4", dbname=dbname)
    imgid.plot_fans(ax=ax, **kwargs)


