import seaborn as _sns
import numpy as _np

TALK_MIN_FONT_PT = 24
"""Slide-deck guideline: every glyph at least this big."""


# In seaborn's "talk" context (font_scale=1.0), the smallest text element
# (tick labels) lands at ~16.5 pt. We scale by ``min_pt / 16.5`` so even the
# smallest element meets the floor; all other proportions are seaborn's.
_SNS_TALK_SMALLEST_BASELINE_PT = 16.5


def apply_talk_context(min_pt: int = TALK_MIN_FONT_PT) -> None:
    """Apply seaborn's "talk" context, scaled so the smallest text element is
    at least ``min_pt`` (default 24 — the EGU26 slide-deck guideline).

    Thin wrapper over :func:`seaborn.set_context` — we delegate all element
    proportions (titles vs axis labels vs ticks vs legend) to seaborn and
    only choose the overall scaling factor.
    """
    _sns.set_context("talk", font_scale=min_pt / _SNS_TALK_SMALLEST_BASELINE_PT)


def histogram_kde(
    values,
    ax=None,
    *,
    bins: int = 60,
    upper_quantile: float = 0.995,
    color: str = "#1f77b4",
    kde: bool = True,
    show_median: bool = True,
    show_mean: bool = True,
    label: str | None = None,
):
    """Histogram + optional KDE overlay + optional median/mean reference lines.

    Returns the axes used. Caller is responsible for figure creation, titles,
    axis labels, and saving. Uses seaborn for the histogram so the KDE is
    rendered consistently with the binned data.
    """
    arr = _np.asarray(values, dtype=float)
    arr = arr[_np.isfinite(arr)]
    if ax is None:
        _, ax = plt.subplots()
    upper = float(_np.quantile(arr, upper_quantile)) if arr.size else 1.0
    bin_edges = _np.linspace(0, upper, bins)
    _sns.histplot(
        arr, bins=bin_edges, kde=kde, stat="density",
        color=color, edgecolor="white", linewidth=0.4,
        line_kws=dict(linewidth=2.0, color="#d62728"),
        ax=ax, label=label,
    )
    if show_median and arr.size:
        med = float(_np.median(arr))
        ax.axvline(med, color="black", linestyle=":", linewidth=1.2,
                   label=f"median {med:.2f}")
    if show_mean and arr.size:
        mn = float(_np.mean(arr))
        ax.axvline(mn, color="black", linestyle="--", linewidth=1.2,
                   label=f"mean {mn:.2f}")
    ax.set_xlim(0, upper)
    return ax


def kde_per_group(
    df,
    group_col: str,
    value_col: str,
    ax=None,
    *,
    palette: str = "viridis",
    upper_quantile: float = 0.995,
    show_background: bool = True,
    label_fn=None,
):
    """One KDE per ``group_col`` value of ``df[value_col]``, optional shared faint hist background."""
    if ax is None:
        _, ax = plt.subplots()
    vals = df[value_col].to_numpy(dtype=float)
    vals = vals[_np.isfinite(vals)]
    upper = float(_np.quantile(vals, upper_quantile)) if vals.size else 1.0
    if show_background and vals.size:
        ax.hist(
            vals, bins=_np.linspace(0, upper, 60),
            color="#cccccc", alpha=0.45, density=True,
            edgecolor="white", linewidth=0.3,
            label=f"all  N={len(vals):,}",
        )
    groups = sorted(df[group_col].dropna().unique().tolist())
    colors = _sns.color_palette(palette, n_colors=max(len(groups), 1))
    for color, g in zip(colors, groups):
        sub = df.loc[df[group_col] == g, value_col].to_numpy(dtype=float)
        sub = sub[_np.isfinite(sub)]
        if sub.size < 2:
            continue
        if label_fn is not None:
            lbl = label_fn(g, sub)
        else:
            lbl = f"{group_col} {g}  N={len(sub):,}"
        _sns.kdeplot(sub, ax=ax, color=color, linewidth=2.6,
                     clip=(0, upper), label=lbl)
    ax.set_xlim(0, upper)
    return ax


def smallmult_highlight_grid(
    df,
    panel_col: str,
    x_col: str,
    y_col: str,
    *,
    yerr=None,
    ncols: int = 3,
    x_lim=None,
    palette: str = "viridis",
    figsize=None,
    title_fmt: str = "{panel_col} {value}  (N={n})",
):
    """Small-multiples grid; one panel per ``panel_col`` value highlights its own subset
    on a faint grey background of all other panels' points.

    ``yerr`` may be a tuple of column names (low, high) for asymmetric IQR-style
    error bars, or None.
    Returns the matplotlib Figure.
    """
    panels = sorted(df[panel_col].dropna().unique().tolist())
    n = len(panels)
    nrows = (n + ncols - 1) // ncols
    fig, axes = plt.subplots(nrows, ncols, figsize=figsize or (4 * ncols, 3 * nrows),
                             sharex=True, sharey=True, dpi=120)
    axes_flat = list(_np.array(axes).reshape(-1))
    colors = _sns.color_palette(palette, n_colors=max(n, 1))
    for ax, panel_value, color in zip(axes_flat, panels, colors):
        other = df[df[panel_col] != panel_value]
        ax.scatter(other[x_col], other[y_col],
                   color="#cccccc", s=40, alpha=0.55, edgecolor="none")
        this = df[df[panel_col] == panel_value].sort_values(x_col)
        if yerr is not None:
            lo_col, hi_col = yerr
            yerrs = [this[y_col] - this[lo_col], this[hi_col] - this[y_col]]
            ax.errorbar(this[x_col], this[y_col], yerr=yerrs,
                        fmt="o", color=color, ecolor=color, alpha=0.9,
                        markersize=8, linewidth=2.0, capsize=0)
        else:
            ax.scatter(this[x_col], this[y_col], color=color,
                       s=80, alpha=0.9, edgecolor="white", linewidth=0.4)
        ax.set_title(title_fmt.format(panel_col=panel_col, value=panel_value, n=len(this)))
        if x_lim is not None:
            ax.set_xlim(*x_lim)
    for ax in axes_flat[n:]:
        ax.set_visible(False)
    fig.tight_layout()
    return fig

